# Weights of the seven portfolios, one column each, for every series that any
# of them holds at one percent or more. Built from a single long data frame
# with one row per portfolio and series.
w_long <- dplyr::bind_rows(lapply(names(ports), function(p)
  tibble::tibble(portfolio = p, series = names(ports[[p]]), weight = as.numeric(ports[[p]]))
)) |>
